def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    fg = [c for c in np.unique(g) if c != bg]
    spans = {}
    for y in range(g.shape[0]):
        xs = [x for x in range(g.shape[1]) if g[y, x] != bg]
        if len(xs) >= 2:
            spans[y] = (min(xs), max(xs))
    if not spans:
        emit(g, "No row has a pair of coloured cells; nothing to fill.")
        return g
    m = min(r - l for l, r in spans.values())
    for y, (l, r) in sorted(spans.items()):
        if r - l == m:
            col = g[y, l]
            g[y, l:r + 1] = col
            emit(g, f"Row {y} has the narrowest pair (columns {l} and {r}, span {m}); fill between them with colour {col}.")
    emit(g, "All narrowest-span rows are filled; this is the final grid.")
    return g
